'use client'

import Link from 'next/link'
import { useEffect, useState } from 'react'
import { ArrowRight, Clock3, Ruler, Sparkles } from 'lucide-react'
import UserMenu from '@/components/UserMenu'
import ProtectedRoute from '@/components/ProtectedRoute'

const recentLooks = [
  { name: 'Soft tailoring', detail: 'Linen shirt · Wide-leg trouser', tone: 'bg-[#e9ded4]', accent: 'bg-[#b98270]' },
  { name: 'Weekend ease', detail: 'Silk blouse · Straight denim', tone: 'bg-[#ead5de]', accent: 'bg-[#9b6980]' },
  { name: 'Everyday edit', detail: 'Neutral layers · Soft loafers', tone: 'bg-[#d9ddd2]', accent: 'bg-[#7d8971]' },
]

function InternalHome() {
  const [isReturningUser, setIsReturningUser] = useState(false)
  const [fullName, setFullName] = useState('')

  useEffect(() => {
    try { const stored = JSON.parse(sessionStorage.getItem('lookfit_mock_auth') || 'null'); setFullName(String(stored?.fullName || stored?.name || '').trim()) } catch {}
    
    const hasVisitedHome = localStorage.getItem('lookfit_home_visited') === 'true'
    setIsReturningUser(hasVisitedHome)
    localStorage.setItem('lookfit_home_visited', 'true')
  }, [])

  return <main className="min-h-screen bg-[#faf8f5] text-[#2b2623]"><header className="sticky top-0 z-20 border-b border-[#e9e0d9] bg-[#fffdfb]/95 backdrop-blur"><div className="mx-auto flex h-[82px] max-w-[1180px] items-center justify-between px-5 sm:px-8"><Link href="/home" aria-label="LookFit home"><img src="https://hebbkx1anhila5yf.public.blob.vercel-storage.com/lookfit-logo-new-SgG0KVJPTSg9JSHg2oL4vzSMpzFO80.png" alt="LookFit" className="h-12 w-[150px] object-cover object-center" /></Link><nav aria-label="Primary navigation" className="flex items-center gap-5 text-xs text-[#766a63] sm:gap-7"><Link className="relative font-medium text-[#b5527a] after:absolute after:-bottom-2 after:left-0 after:right-0 after:h-0.5 after:rounded-full after:bg-[#b5527a]" href="/home">Home</Link><Link href="/profile">Profile</Link><Link href="/recommendation">Recommendation</Link><Link href="/history">History</Link></nav><UserMenu /></div></header><div className="mx-auto max-w-[1180px] px-5 py-10 sm:px-8 lg:py-14"><section className="flex flex-col justify-between gap-7 lg:flex-row lg:items-end"><div><div className="mb-4 flex items-center gap-2 text-[10px] font-bold uppercase tracking-[0.2em] text-[#b5527a]">Personal dashboard <span className="h-1 w-1 rounded-full bg-[#c9796e]" /> LookFit</div><h1 className="font-serif text-5xl tracking-[-2px] text-[#302824] sm:text-6xl">Welcome back, <em className="text-[#b5527a]">{fullName}.</em></h1><p className="mt-4 max-w-lg text-sm leading-6 text-[#887b73]">Your wardrobe is ready. Pick up where you left off or find a fresh way to wear what you already own.</p></div></section><section className="mt-10 grid gap-4 md:grid-cols-3"><Link href="/recommendation" className="group rounded-2xl bg-[#b5527a] p-6 text-white shadow-[0_12px_28px_rgba(181,82,122,0.14)] transition hover:-translate-y-1"><div className="mb-12 flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-full bg-white/15"><Sparkles size={18} /></span><ArrowRight size={18} className="transition group-hover:translate-x-1" /></div><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-white/70">Quick styling</p><h2 className="mt-2 font-serif text-2xl">Create a new look</h2><p className="mt-2 text-xs leading-5 text-white/75">Build an outfit from your wardrobe in a few thoughtful steps.</p></Link><Link href="/profile" className="group rounded-2xl border border-[#e9e0d9] bg-[#fffdfb] p-6 transition hover:-translate-y-1 hover:border-[#c9796e]"><div className="mb-12 flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-full bg-[#f3e2e2] text-[#b5527a]"><Ruler size={18} /></span><ArrowRight size={18} className="text-[#c9b9b0] transition group-hover:translate-x-1" /></div><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#b5527a]">Your fit</p><h2 className="mt-2 font-serif text-2xl text-[#403733]">Complete your profile</h2><p className="mt-2 text-xs leading-5 text-[#9a8d84]">Add your measurements to make every recommendation more personal.</p></Link><Link href="/history" className="group rounded-2xl border border-[#e9e0d9] bg-[#f5eee9] p-6 transition hover:-translate-y-1 hover:border-[#c9796e]"><div className="mb-12 flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-full bg-[#fffdfb] text-[#b5527a]"><Clock3 size={18} /></span><ArrowRight size={18} className="text-[#c9b9b0] transition group-hover:translate-x-1" /></div><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#b5527a]">Your activity</p><h2 className="mt-2 font-serif text-2xl text-[#403733]">See recent looks</h2><p className="mt-2 text-xs leading-5 text-[#9a8d84]">Revisit the combinations you saved and loved.</p></Link></section><section className="mt-12"><div className="mb-5 flex items-end justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-[#b5527a]">From your wardrobe</p><h2 className="mt-2 font-serif text-3xl text-[#403733]">Recent edits</h2></div><Link href="/history" className="flex items-center gap-1 text-xs font-medium text-[#9b5c70]">View history <ArrowRight size={14} /></Link></div><div className="grid gap-4 md:grid-cols-3">{recentLooks.map(look => <Link href="/recommendation" key={look.name} className="group rounded-2xl border border-[#e9e0d9] bg-[#fffdfb] p-3 transition hover:-translate-y-1 hover:shadow-[0_12px_24px_rgba(101,70,60,0.07)]"><div className={`relative grid aspect-[1.65] place-items-center overflow-hidden rounded-xl ${look.tone}`}><div className={`h-20 w-16 rounded-t-[45%] rounded-b-lg ${look.accent} opacity-75 transition group-hover:scale-105`} /><span className="absolute bottom-3 left-3 rounded-full bg-white/70 px-2 py-1 text-[9px] uppercase tracking-wider text-[#766a63]">Saved look</span></div><div className="px-1 pb-1 pt-3"><h3 className="text-sm font-medium text-[#403733]">{look.name}</h3><p className="mt-1 text-[11px] text-[#9a8d84]">{look.detail}</p></div></Link>)}</div></section></div></main>
}

export default function HomePage() { return <ProtectedRoute><InternalHome /></ProtectedRoute> }
